#!/usr/bin/env bash
# Rebuild a scratch database and run the rules tests.
set -euo pipefail
cd "$(dirname "$0")/.."
P="psql -h ${PGHOST:-/var/tmp} -p ${PGPORT:-5433} -U ${PGUSER:-postgres} -v ON_ERROR_STOP=1 -q"
$P -d postgres -c 'drop database if exists eleade_test' -c 'create database eleade_test'
$P -d eleade_test -f tests/shim.sql -f migrations/0001_init.sql -f migrations/0002_hardening.sql -f migrations/0003_assessments_and_payments.sql -f migrations/0004_rename_players.sql -f migrations/0005_regular_sessions.sql -f migrations/0006_session_payment_edit.sql -f migrations/0007_coach_invoices.sql -f migrations/0008_stats_and_expiry.sql -f migrations/0009_stripe_payments.sql -f migrations/0010_stats_include_documentation.sql -f migrations/0011_stats_history.sql -f migrations/0012_stats_history_pay.sql -f migrations/0013_stats_history_jani_luca.sql -f migrations/0014_bookings_and_schedule.sql -f migrations/0015_session_durations.sql -f migrations/0016_stripe_session_payments.sql -f migrations/0017_enquiries.sql -f migrations/0018_complete_after_end.sql -f migrations/0019_last_location.sql -f migrations/0020_enquiry_process.sql -f migrations/0021_cash_kept_by_coach.sql -f migrations/0022_paid_separately.sql -f migrations/0023_pair_credits.sql -f migrations/0025_reactivate_on_booking.sql -f migrations/0027_invoice_any_time_and_stripe_name.sql -f migrations/0028_edit_session.sql -f migrations/0029_owner_weeks.sql -f migrations/0030_update_invoice.sql -f migrations/0031_session_prep.sql -f migrations/0032_calendar_feed.sql -f migrations/0033_invoice_reminders.sql -f migrations/0034_edit_ledger.sql -f migrations/0035_cancel_in_advance.sql -f migrations/0036_pair_price.sql -f migrations/0037_opponent.sql -f migrations/0038_drive.sql -f migrations/0039_enquiries_team_locations.sql -f migrations/0040_invoice_planned_weekend.sql -f migrations/0041_docs_videos_admin_hours.sql -f migrations/0042_reminder_packages.sql -f migrations/0043_payment_plans.sql -f migrations/0044_player_details_feedback.sql -f migrations/0045_change_plan.sql -f migrations/0046_feedback_regulars.sql -f migrations/0047_casual_players_never_package.sql -f migrations/0048_feedback_not_before.sql
$P -d eleade_test -f tests/rules_test.sql
